    /// <summary>
    /// Values shown to ordinary Revit users for one maintenance-preview DirectShape.
    /// Six fields are generated by the plug-in. MaintenanceConclusion and
    /// ProfessionalNote are user-editable and are kept when their value is null, so a
    /// regeneration need not erase professional confirmation already entered in Revit.
    /// </summary>
    public sealed class MaintenanceParameterValues
    {
        public string ElementName { get; set; }
        public string CeilingGroup { get; set; }
        public string EntryGroup { get; set; }
        public string ElementRole { get; set; }
        public string MaintenanceTarget { get; set; }
        public string MaintenanceConclusion { get; set; }
        public string DecisionNote { get; set; }
        public string ProfessionalNote { get; set; }
    }

