        public static string GetDefaultSharedParameterFilePath()
        {
            string assemblyFolder = Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
            return Path.Combine(assemblyFolder ?? string.Empty, "Resources", SharedParameterFileName);
        }

        /// <summary>
        /// Ensures all eight shared parameters exist as Generic Model instance parameters.
        /// Existing bindings are identified by GUID, not name.  An existing instance binding
        /// is widened to Generic Models without dropping any previously bound category.
        /// </summary>
        public static void EnsureSharedParameters(Document doc, string sharedParameterFilePath)
        {
            RequireModifiableDocument(doc);
            if (string.IsNullOrWhiteSpace(sharedParameterFilePath) || !File.Exists(sharedParameterFilePath))
                throw new FileNotFoundException("找不到维修可达共享参数文件。", sharedParameterFilePath);

            string originalFile = doc.Application.SharedParametersFilename;
            try
            {
                doc.Application.SharedParametersFilename = sharedParameterFilePath;
                DefinitionFile definitionFile = doc.Application.OpenSharedParameterFile();
                if (definitionFile == null)
                    throw new InvalidOperationException("无法打开维修可达共享参数文件：" + sharedParameterFilePath);

                foreach (ParameterSpec spec in ParameterSpecs)
                {
                    ExternalDefinition fileDefinition = FindExternalDefinition(definitionFile, spec.Guid);
                    if (fileDefinition == null)
                        throw new InvalidOperationException("共享参数文件缺少 GUID " + spec.Guid + "（" + spec.Name + "）。");
                    if (!string.Equals(fileDefinition.Name, spec.Name, StringComparison.Ordinal))
                        throw new InvalidOperationException("共享参数 GUID " + spec.Guid + " 的名称不匹配，期望“" + spec.Name + "”，实际“" + fileDefinition.Name + "”。");
                    if (fileDefinition.UserModifiable != spec.UserModifiable)
                        throw new InvalidOperationException("共享参数“" + spec.Name + "”的用户可编辑设置与插件规则不一致。");

                    EnsureGenericModelInstanceBinding(doc, fileDefinition, spec);
                }
            }
            finally
            {
                doc.Application.SharedParametersFilename = originalFile;
            }
        }

        /// <summary>
        /// Writes the eight user-facing values to one maintenance DirectShape by GUID.
        /// Null MaintenanceConclusion/ProfessionalNote values preserve an existing
        /// user's confirmation. Null DecisionNote preserves the current generated reason.
        /// </summary>
        public static void ApplyToDirectShape(DirectShape shape, MaintenanceParameterValues values)
        {
            if (shape == null) throw new ArgumentNullException("shape");
            if (values == null) throw new ArgumentNullException("values");
            RequireModifiableDocument(shape.Document);
            if (shape.Category == null || shape.Category.BuiltInCategory != BuiltInCategory.OST_GenericModel)
                throw new ArgumentException("维修可达参数只能赋给常规模型 DirectShape。", "shape");

            SetRequiredText(shape, ElementNameGuid, ParameterElementName, values.ElementName);
            SetRequiredText(shape, CeilingGroupGuid, ParameterCeilingGroup, values.CeilingGroup);
            SetRequiredText(shape, EntryGroupGuid, ParameterEntryGroup, values.EntryGroup);
            SetRequiredText(shape, ElementRoleGuid, ParameterElementRole, values.ElementRole);
            SetRequiredText(shape, MaintenanceTargetGuid, ParameterMaintenanceTarget, values.MaintenanceTarget);
            if (values.MaintenanceConclusion != null)
                SetRequiredText(shape, MaintenanceConclusionGuid, ParameterMaintenanceConclusion,
                    NormalizeConclusion(values.MaintenanceConclusion));

            SetOptionalText(shape, DecisionNoteGuid, ParameterDecisionNote, values.DecisionNote);
            SetOptionalText(shape, ProfessionalNoteGuid, ParameterProfessionalNote, values.ProfessionalNote);
        }

        /// <summary>
        /// Creates or refreshes CODEX-owned materials and parameter filters in a specified
        /// non-template 3D view.  Element overrides are deliberately not used.
        /// </summary>
        public static void EnsureViewPresentation(Document doc, View3D view)
        {
            RequireModifiableDocument(doc);
            if (view == null) throw new ArgumentNullException("view");
            Element viewFromDocument = doc.GetElement(view.Id);
            if (viewFromDocument == null ||
                !string.Equals(viewFromDocument.UniqueId, view.UniqueId, StringComparison.Ordinal))
                throw new ArgumentException("视图不属于指定文档。", "view");
            if (view.IsTemplate) throw new ArgumentException("请指定普通三维视图，不能指定视图样板。", "view");
            if (!view.AreGraphicsOverridesAllowed())
                throw new InvalidOperationException("指定的三维视图不允许图形替换。");

            FillPatternElement solidFill = FindSolidFill(doc);
            if (solidFill == null)
                throw new InvalidOperationException("项目中找不到实心填充图案，无法创建维修可达显示样式。");

            // Older prototypes used an unversioned prefix and no ownership marker.
            // Leave those project resources untouched, but remove their exact filters
            // from this dedicated presentation view so they cannot override v1 colors.
            foreach (ElementId appliedFilterId in view.GetFilters().ToList())
            {
                FilterElement legacy = doc.GetElement(appliedFilterId) as FilterElement;
                if (legacy != null &&
                    legacy.Name.StartsWith(LegacyResourcePrefix, StringComparison.Ordinal) &&
                    !legacy.Name.StartsWith(ResourcePrefix, StringComparison.Ordinal))
                    view.RemoveFilter(appliedFilterId);
            }

            foreach (MaterialSpec materialSpec in MaterialSpecs)
                EnsureMaterial(doc, materialSpec, solidFill.Id);

            ElementId genericModelCategoryId = new ElementId((long)BuiltInCategory.OST_GenericModel);
            IList<ElementId> categories = new List<ElementId> { genericModelCategoryId };
            foreach (FilterSpec spec in FilterSpecs)
            {
                ElementId parameterId = GetSharedParameterElementId(doc, spec.ParameterGuid, spec.Name);
                FilterRule rule = spec.Contains
                    ? ParameterFilterRuleFactory.CreateContainsRule(parameterId, spec.MatchValue)
                    : ParameterFilterRuleFactory.CreateEqualsRule(parameterId, spec.MatchValue);
                ElementFilter elementFilter = new ElementParameterFilter(rule);
                ParameterFilterElement filter = EnsureParameterFilter(doc, spec.Name, categories, elementFilter);
                if (!view.IsFilterApplied(filter.Id)) view.AddFilter(filter.Id);
                view.SetFilterVisibility(filter.Id, true);
                view.SetIsFilterEnabled(filter.Id, true);
                view.SetFilterOverrides(filter.Id,
                    spec.IsConclusion
                        ? CreateConclusionOverrides(spec.Color, solidFill.Id)
                        : CreateRoleOverrides(
                            spec.Color,
                            solidFill.Id,
                            spec.FillSurfaces,
                            spec.Transparency));
            }
        }

        /// <summary>
        /// Returns a CODEX material suitable for geometry creation.  The presentation
        /// resources must already have been ensured inside the current transaction.
        /// </summary>
        public static ElementId GetConclusionMaterialId(Document doc, string conclusion)
        {
            string normalized = NormalizeConclusion(conclusion);
            string name = ResourcePrefix + "材质_" + normalized;
            Material material = FindMaterial(doc, name);
            if (material == null)
                throw new InvalidOperationException("缺少维修可达材质“" + name + "”，请先调用 EnsureViewPresentation。");
            if (!IsOwnedResource(material))
                throw new InvalidOperationException("同名材质“" + name + "”不属于 OpenRevit，拒绝接管。");
            return material.Id;
        }

        private static void EnsureGenericModelInstanceBinding(Document doc, ExternalDefinition fileDefinition, ParameterSpec spec)
        {
            Definition existingDefinition;
            Binding existingBinding;
            FindBindingByGuid(doc, spec.Guid, out existingDefinition, out existingBinding);

            if (existingDefinition != null)
            {
                if (!string.Equals(existingDefinition.Name, spec.Name, StringComparison.Ordinal))
                    throw new InvalidOperationException("项目中 GUID " + spec.Guid + " 已被参数“" + existingDefinition.Name + "”使用，不能安全替换为“" + spec.Name + "”。");
                InstanceBinding instanceBinding = existingBinding as InstanceBinding;
                if (instanceBinding == null)
                    throw new InvalidOperationException("共享参数“" + spec.Name + "”已以类型参数绑定，不会自动破坏性地改为实例参数。");

                Category genericModel = doc.Settings.Categories.get_Item(BuiltInCategory.OST_GenericModel);
                if (instanceBinding.Categories.Contains(genericModel)) return;

                CategorySet expanded = doc.Application.Create.NewCategorySet();
                foreach (Category category in instanceBinding.Categories) expanded.Insert(category);
                expanded.Insert(genericModel);
                bool rebound = doc.ParameterBindings.ReInsert(
                    existingDefinition,
                    doc.Application.Create.NewInstanceBinding(expanded),
                    GroupTypeId.IdentityData);
                if (!rebound)
                    throw new InvalidOperationException("无法将共享参数“" + spec.Name + "”的既有绑定安全扩展到常规模型。");
                return;
            }

            ThrowIfNameIsBoundToDifferentGuid(doc, spec.Name, spec.Guid);
            CategorySet categories = doc.Application.Create.NewCategorySet();
            categories.Insert(doc.Settings.Categories.get_Item(BuiltInCategory.OST_GenericModel));
            bool inserted = doc.ParameterBindings.Insert(
                fileDefinition,
                doc.Application.Create.NewInstanceBinding(categories),
                GroupTypeId.IdentityData);
            if (!inserted)
                throw new InvalidOperationException("无法将共享参数“" + spec.Name + "”绑定到常规模型实例。");
        }

        private static ExternalDefinition FindExternalDefinition(DefinitionFile file, Guid guid)
        {
            foreach (DefinitionGroup group in file.Groups)
            {
                foreach (Definition definition in group.Definitions)
                {
                    ExternalDefinition external = definition as ExternalDefinition;
                    if (external != null && external.GUID == guid) return external;
                }
            }
            return null;
        }

        private static void FindBindingByGuid(Document doc, Guid guid, out Definition definition, out Binding binding)
        {
            definition = null;
            binding = null;
            DefinitionBindingMapIterator iterator = doc.ParameterBindings.ForwardIterator();
            iterator.Reset();
            while (iterator.MoveNext())
            {
                Definition candidate = iterator.Key;
                Guid? candidateGuid = GetDefinitionGuid(doc, candidate);
                if (!candidateGuid.HasValue || candidateGuid.Value != guid) continue;
                definition = candidate;
                binding = iterator.Current as Binding;
                return;
            }
        }

        private static Guid? GetDefinitionGuid(Document doc, Definition definition)
        {
            ExternalDefinition external = definition as ExternalDefinition;
            if (external != null) return external.GUID;
            InternalDefinition internalDefinition = definition as InternalDefinition;
            if (internalDefinition == null) return null;
            SharedParameterElement shared = doc.GetElement(internalDefinition.Id) as SharedParameterElement;
            return shared == null ? (Guid?)null : shared.GuidValue;
        }

        private static void ThrowIfNameIsBoundToDifferentGuid(Document doc, string name, Guid intendedGuid)
        {
            DefinitionBindingMapIterator iterator = doc.ParameterBindings.ForwardIterator();
            iterator.Reset();
            while (iterator.MoveNext())
            {
                Definition candidate = iterator.Key;
                if (!string.Equals(candidate.Name, name, StringComparison.Ordinal)) continue;
                Guid? existingGuid = GetDefinitionGuid(doc, candidate);
                if (!existingGuid.HasValue || existingGuid.Value != intendedGuid)
                    throw new InvalidOperationException("项目中已有同名但 GUID 不同的参数“" + name + "”，为避免误写已停止绑定。");
            }
        }

        private static void SetRequiredText(Element element, Guid guid, string name, string value)
        {
            Parameter parameter = element.get_Parameter(guid);
            if (parameter == null)
                throw new InvalidOperationException("常规模型缺少共享参数“" + name + "”，请先完成参数绑定。");
            if (parameter.IsReadOnly)
                throw new InvalidOperationException("共享参数“" + name + "”对 API 不可写。");
            if (!parameter.Set(value ?? string.Empty))
                throw new InvalidOperationException("共享参数“" + name + "”赋值失败。");
        }

        private static void SetOptionalText(Element element, Guid guid, string name, string value)
        {
            if (value == null) return;
            SetRequiredText(element, guid, name, value);
        }

        private static string NormalizeConclusion(string value)
        {
            if (string.Equals(value, ConclusionPending, StringComparison.Ordinal)) return ConclusionPending;
            if (string.Equals(value, ConclusionMaintainable, StringComparison.Ordinal)) return ConclusionMaintainable;
            if (string.Equals(value, ConclusionNotMaintainable, StringComparison.Ordinal)) return ConclusionNotMaintainable;
            if (string.Equals(value, ConclusionError, StringComparison.Ordinal)) return ConclusionError;
            return ConclusionError;
        }

        private static ElementId GetSharedParameterElementId(Document doc, Guid guid, string ownerName)
        {
            SharedParameterElement parameter = SharedParameterElement.Lookup(doc, guid);
            if (parameter == null)
                throw new InvalidOperationException("缺少用于过滤器“" + ownerName + "”的共享参数，请先调用 EnsureSharedParameters。");
            return parameter.Id;
        }

        private static ParameterFilterElement EnsureParameterFilter(
            Document doc,
            string name,
            IList<ElementId> categories,
            ElementFilter elementFilter)
        {
            FilterElement nameCollision = new FilteredElementCollector(doc)
                .OfClass(typeof(FilterElement))
                .Cast<FilterElement>()
                .FirstOrDefault(x => string.Equals(x.Name, name, StringComparison.Ordinal));
            ParameterFilterElement filter = nameCollision as ParameterFilterElement;
            if (nameCollision != null && filter == null)
                throw new InvalidOperationException("项目中已有非参数过滤器使用 CODEX 保留名称“" + name + "”。");

            if (filter == null)
            {
                filter = ParameterFilterElement.Create(doc, name, categories, elementFilter);
                MarkOwnedResource(filter, "ParameterFilter");
                return filter;
            }

            if (!IsOwnedResource(filter))
                throw new InvalidOperationException(
                    "项目中已有同名参数过滤器“" + name + "”，但它不属于 OpenRevit；为保护用户资源，本次拒绝覆盖。");

            filter.SetCategories(categories);
            // False means the existing rules were already equivalent, not failure.
            filter.SetElementFilter(elementFilter);
            return filter;
        }

        private static OverrideGraphicSettings CreateRoleOverrides(
            Color color,
            ElementId solidFillId,
            bool fillSurfaces,
            int transparency)
        {
            OverrideGraphicSettings graphics = new OverrideGraphicSettings();
            graphics.SetProjectionLineColor(color);
            graphics.SetProjectionLineWeight(6);
            graphics.SetCutLineColor(color);
            graphics.SetCutLineWeight(6);
            if (fillSurfaces)
            {
                graphics.SetSurfaceForegroundPatternId(solidFillId);
                graphics.SetSurfaceForegroundPatternColor(color);
                graphics.SetSurfaceForegroundPatternVisible(true);
                graphics.SetCutForegroundPatternId(solidFillId);
                graphics.SetCutForegroundPatternColor(color);
                graphics.SetCutForegroundPatternVisible(true);
                graphics.SetSurfaceTransparency(Math.Max(0, Math.Min(100, transparency)));
            }
            return graphics;
        }

        private static OverrideGraphicSettings CreateConclusionOverrides(Color color, ElementId solidFillId)
        {
            OverrideGraphicSettings graphics = new OverrideGraphicSettings();
            graphics.SetSurfaceForegroundPatternId(solidFillId);
            graphics.SetSurfaceForegroundPatternColor(color);
            graphics.SetSurfaceForegroundPatternVisible(true);
            graphics.SetCutForegroundPatternId(solidFillId);
            graphics.SetCutForegroundPatternColor(color);
            graphics.SetCutForegroundPatternVisible(true);
            graphics.SetSurfaceTransparency(12);
            return graphics;
        }

        private static FillPatternElement FindSolidFill(Document doc)
        {
            return new FilteredElementCollector(doc)
                .OfClass(typeof(FillPatternElement))
                .Cast<FillPatternElement>()
                .FirstOrDefault(x => x.GetFillPattern().IsSolidFill);
        }

        private static void EnsureMaterial(Document doc, MaterialSpec spec, ElementId solidFillId)
        {
            Material material = FindMaterial(doc, spec.Name);
            if (material == null)
            {
                material = doc.GetElement(Material.Create(doc, spec.Name)) as Material;
                if (material != null) MarkOwnedResource(material, "Material");
            }
            if (material == null)
                throw new InvalidOperationException("无法创建材质“" + spec.Name + "”。");
            if (!IsOwnedResource(material))
                throw new InvalidOperationException(
                    "项目中已有同名材质“" + spec.Name + "”，但它不属于 OpenRevit；为保护用户资源，本次拒绝覆盖。");

            material.Color = spec.Color;
            material.Transparency = spec.Transparency;
            material.UseRenderAppearanceForShading = false;
            material.SurfaceForegroundPatternId = solidFillId;
            material.SurfaceForegroundPatternColor = spec.Color;
            material.CutForegroundPatternId = solidFillId;
            material.CutForegroundPatternColor = spec.Color;
        }

        private static Material FindMaterial(Document doc, string name)
        {
            return new FilteredElementCollector(doc)
                .OfClass(typeof(Material))
                .Cast<Material>()
                .FirstOrDefault(x => string.Equals(x.Name, name, StringComparison.Ordinal));
        }

        private static bool IsOwnedResource(Element element)
        {
            if (element == null) return false;
            Schema schema = Schema.Lookup(ResourceOwnershipSchemaGuid);
            if (schema == null) return false;
            Entity entity = element.GetEntity(schema);
            if (!entity.IsValid()) return false;
            Field ownerField = schema.GetField("OwnerId");
            return ownerField != null && string.Equals(
                entity.Get<string>(ownerField),
                ResourceOwnerId,
                StringComparison.Ordinal);
        }

        private static void MarkOwnedResource(Element element, string resourceKind)
        {
            if (element == null) throw new ArgumentNullException("element");
            Schema schema = GetOrCreateResourceOwnershipSchema();
            var entity = new Entity(schema);
            entity.Set(schema.GetField("OwnerId"), ResourceOwnerId);
            entity.Set(schema.GetField("ResourceKind"), resourceKind ?? string.Empty);
            element.SetEntity(entity);
        }

        private static Schema GetOrCreateResourceOwnershipSchema()
        {
            Schema existing = Schema.Lookup(ResourceOwnershipSchemaGuid);
            if (existing != null) return existing;

            var builder = new SchemaBuilder(ResourceOwnershipSchemaGuid);
            builder.SetSchemaName("OpenRevitMaintenanceResourceOwnership");
            builder.SetReadAccessLevel(AccessLevel.Public);
            builder.SetWriteAccessLevel(AccessLevel.Public);
            builder.AddSimpleField("OwnerId", typeof(string));
            builder.AddSimpleField("ResourceKind", typeof(string));
            return builder.Finish();
        }

        private static void RequireModifiableDocument(Document doc)
        {
            if (doc == null) throw new ArgumentNullException("doc");
            if (!doc.IsModifiable)
                throw new InvalidOperationException("请在调用 MaintenanceParameterService 前启动 Revit 事务。");
        }
    }
}
